/* Helpers (no dependencies):
     D.byNpsn(npsn)          one row or null
     D.within(km, levels)    rows within km of the Mabes TNI centre, optional level filter (['SMA','SMK','MA'])
     D.totals(km, levels)    { schools, students, age17, resmi, closedLikely } over those rows (null counts are skipped;
                             closedLikely = rows marked "kemungkinan tidak aktif", counted in schools)
   D.extra holds Dapodik schools within 30 km that the app's list lacks; the helpers never read it. */
(function (D) {
  'use strict';
  if (!D || !D.rows) return;
  var byN = null;
  D.byNpsn = function (npsn) {
    if (!byN) { byN = {}; D.rows.forEach(function (r) { if (r.npsn && !byN[r.npsn]) byN[r.npsn] = r; }); }
    return byN[String(npsn)] || null;
  };
  D.within = function (km, levels) {
    var lim = typeof km === 'number' && isFinite(km) ? km : D.meta.radiusKm;
    return D.rows.filter(function (r) { return r.km <= lim && (!levels || levels.indexOf(r.level) >= 0); });
  };
  D.totals = function (km, levels) {
    var t = { schools: 0, students: 0, age17: 0, resmi: 0, closedLikely: 0 };
    D.within(km, levels).forEach(function (r) {
      t.schools++;
      if (r.students != null) t.students += r.students;
      if (r.age17 != null) t.age17 += r.age17;
      if (r.studentsSource === 'resmi') t.resmi++;
      if (r.closedLikely) t.closedLikely++;
    });
    return t;
  };
})(typeof window !== 'undefined' ? window.MCD_SCHOOL_STUDENTS : undefined);
